cd /tmp/vally-eval-trial-g5Fr90 && python3 - <<'E'
p='payment-integration-test/pom.xml'
s=open(p).read()
s=s.replace('''    <dependency>
      <groupId>org.junit.jupiter</groupId>''','''    <dependency>
      <groupId>com.tngtech.archunit</groupId>
      <artifactId>archunit-junit5</artifactId>
      <version>1.3.0</version>
      <scope>test</scope>
    </dependency>
    <dependency>
      <groupId>org.junit.jupiter</groupId>''',1)
open(p,'w').write(s)
E
d=payment-integration-test/src/test/java/com/example/payment/integrationtest/architecture
mkdir -p $d && cat > $d/LayerDependencyTest.java <<'E'
package com.example.payment.integrationtest.architecture;

import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.junit.AnalyzeClasses;
import com.tngtech.archunit.junit.ArchTest;
import com.tngtech.archunit.lang.ArchRule;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes;

@AnalyzeClasses(packages = "com.example.payment", importOptions = ImportOption.DoNotIncludeTests.class)
class LayerDependencyTest {

    // Allow-lists: only pure language packages, so I/O, network, persistence and frameworks all fail.
    @ArchTest
    static final ArchRule domainDependsOnlyOnDomainAndLanguageCore =
        classes().that().resideInAPackage("com.example.payment.domain..")
            .should().onlyDependOnClassesThat().resideInAnyPackage(
                "com.example.payment.domain..", "java.lang..", "java.math..", "java.util..");

    @ArchTest
    static final ArchRule applicationDependsOnlyOnApplicationDomainAndLanguageCore =
        classes().that().resideInAPackage("com.example.payment.application..")
            .should().onlyDependOnClassesThat().resideInAnyPackage(
                "com.example.payment.application..", "com.example.payment.domain..",
                "java.lang..", "java.math..", "java.util..");

    @ArchTest
    static final ArchRule innerLayersDoNotUseOuterLayers =
        classes().that().resideInAnyPackage("com.example.payment.domain..", "com.example.payment.application..")
            .should().onlyBeAccessed().byClassesThat().resideOutsideOfPackages("com.example.payment.app..")
            .allowEmptyShould(true);
}
E
mvn -q -o verify 2>&1 | tail -30

